3257	// 读取预约清单文件：不可读、不是合法 JSON 均明确失败（绝不按空清单处理）
3258	async function loadFlexManifest(file: string): Promise<unknown> {
3259	  let text: string;
3260	  try {
3261	    text = await readFile(file, 'utf8');
3262	  } catch (err) {
3263	    throw new BizError(`无法读取预约清单 ${file}: ${(err as Error).message}`);
3264	  }
3265	  try {
