3272	// 清单结构（与业务数据无关的纯类型校验）；返回逐项原始记录
3273	function parseFlexPlanShape(raw: unknown, file: string): Array<Record<string, unknown>> {
3274	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
3275	    throw new BizError(`预约清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
3276	  }
3277	  const o = raw as Record<string, unknown>;
3278	  for (const k of Object.keys(o)) {
3279	    if (k !== 'items') throw new BizError(`预约清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
3280	  }
3281	  if (!Array.isArray(o.items)) {
3282	    throw new BizError(`预约清单 ${file} 内容非法：items 必须是非空数组`);
3283	  }
3284	  const items = o.items as unknown[];
3285	  if (items.length === 0) throw new BizError(`预约清单 ${file} 为空：items 至少包含一项预约请求`);
3286	
3287	  const problems: string[] = [];
3288	  const records: Array<Record<string, unknown> | null> = [];
3289	  items.forEach((it, idx) => {
3290	    const at = `第 ${idx + 1} 项`;
3291	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
3292	      problems.push(`${at} 必须是对象`);
3293	      records.push(null);
3294	      return;
3295	    }
3296	    const rec = it as Record<string, unknown>;
3297	    for (const k of Object.keys(rec)) {
3298	      if (k !== 'window' && k !== 'duration' && k !== 'groups') {
3299	        problems.push(`${at} 存在未知字段 “${k}”（只允许 window、duration、groups）`);
3300	      }
3301	    }
3302	    if (typeof rec.window !== 'string' || rec.window === '') {
3303	      problems.push(`${at} 的 window 必须是 窗口开始/窗口结束 形式的非空字符串`);
3304	    }
3305	    if (typeof rec.duration !== 'number' || !Number.isInteger(rec.duration) || rec.duration <= 0) {
3306	      problems.push(`${at} 的 duration 必须是正整数分钟（不超过窗口长度）`);
3307	    }
3308	    if (!Array.isArray(rec.groups) || rec.groups.length === 0) {
3309	      problems.push(`${at} 的 groups 必须是非空数组（至少一个有顺序的需求组）`);
3310	    } else {
3311	      rec.groups.forEach((g, gi) => {
3312	        if (!Array.isArray(g) || g.length === 0) {
3313	          problems.push(`${at} 第 ${gi + 1} 需求组必须是非空数组（可任选其一的候选资源标识）`);
3314	        } else {
3315	          g.forEach((id) => {
3316	            if (typeof id !== 'string' || id === '') {
3317	              problems.push(`${at} 第 ${gi + 1} 需求组含非法候选：候选资源标识必须是非空字符串`);
3318	            }
3319	          });
3320	        }
3321	      });
3322	    }
3323	    records.push(rec);
3324	  });
3325	  if (problems.length > 0) {
3326	    throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3327	  }
3328	  return records as Array<Record<string, unknown>>;
3329	}
3330	
3331	// 逐项做与业务数据相关的校验（窗口真实有效、时长不超过窗口、组内重复与未知资源），
3332	// 收集全部问题后一次性拒绝整单；通过则返回排程项
3333	function parseFlexPlanItems(store: Store, records: Array<Record<string, unknown>>, file: string): FlexPlanItem[] {
3334	  const problems: string[] = [];
3335	  const items: Array<FlexPlanItem | null> = records.map((rec, idx) => {
3336	    const at = `第 ${idx + 1} 项`;
3337	    let ok = true;
3338	
3339	    let win: {start: string; end: string; startMin: number; endMin: number} | null = null;
3340	    try {
3341	      win = parseFlexWindow(rec.window as string, `${at}窗口`);
3342	    } catch (err) {
3343	      if (err instanceof BizError) {
3344	        problems.push(err.message);
3345	        ok = false;
3346	      } else {
3347	        throw err;
3348	      }
3349	    }
3350	
3351	    const duration = rec.duration as number; // 结构校验已保证正整数
3352	    if (win !== null && duration > win.endMin - win.startMin) {
3353	      problems.push(
3354	        `${at} 所需连续时长 ${duration} 分钟超过窗口长度 ${win.endMin - win.startMin} 分钟` +
3355	          `（窗口: ${win.start} → ${win.end}）`,
3356	      );
3357	      ok = false;
3358	    }
3359	
3360	    const groups: RequirementGroup[] = [];
3361	    (rec.groups as string[][]).forEach((ids, gi) => {
3362	      const glabel = `${at} 第 ${gi + 1} 需求组`;
3363	      const seen = new Set<string>();
3364	      const dupes: string[] = [];
3365	      for (const id of ids) {
3366	        if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
3367	        seen.add(id);
3368	      }
3369	      if (dupes.length > 0) {
3370	        problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`);
3371	        ok = false;
3372	      }
3373	      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3374	      if (unknown.length > 0) {
3375	        problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`);
3376	        ok = false;
3377	      }
3378	      groups.push({index: gi + 1, candidates: [...seen].sort()});
3379	    });
3380	
3381	    if (!ok || win === null) return null;
3382	    return {
3383	      index: idx + 1,
3384	      startRaw: win.start,
3385	      endRaw: win.end,
3386	      startMin: win.startMin,
3387	      endMin: win.endMin,
3388	      duration,
3389	      groups,
3390	    };
3391	  });
3392	  if (problems.length > 0) {
3393	    throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3394	  }
3395	  return items as FlexPlanItem[];
3396	}
3397	
3398	// 固定开始分钟上，按需求组顺序字典序升序枚举全部可行资源序列
3399	// （每组恰选一个候选，全部所选互不相同；候选已按标识排序）
3400	function* assignmentsInLexOrder(
3401	  groups: RequirementGroup[],
3402	  usable: (id: string) => boolean,
3403	): Generator<string[], void, undefined> {
3404	  const used = new Set<string>();
3405	  const acc: string[] = [];
3406	  function* rec(g: number): Generator<string[], void, undefined> {
3407	    if (g === groups.length) {
3408	      yield [...acc];
3409	      return;
3410	    }
3411	    for (const id of groups[g].candidates) {
3412	      if (used.has(id) || !usable(id)) continue;
3413	      used.add(id);
3414	      acc.push(id);
3415	      yield* rec(g + 1);
3416	      acc.pop();
3417	      used.delete(id);
3418	    }
3419	  }
3420	  yield* rec(0);
3421	}
3422	
3423	// 联合求解：找到即返回按清单顺序的各项安排（开始分钟 + 各组所选资源），无整体解返回 null。
3424	// 逐项（清单顺序）深度优先：开始分钟升序、同一开始的资源序列字典序升序，
