// 联合求解：找到即返回按清单顺序的各项安排（开始分钟 + 各组所选资源），无整体解返回 null。
// 逐项（清单顺序）深度优先：开始分钟升序、同一开始的资源序列字典序升序，
// 首个完整方案即“逐项先比开始分钟、再比资源序列”的最小方案。
// 项间关系（后项开始 − 前项结束 ∈ [min,max]）只约束可行性，不改变上述取舍。
function solveFlexPlan(store: Store, plan: FlexPlan): FlexPlacement[] | null {
  const items = plan.items;
  // 每项各候选资源的基础空闲段：实际可用时间（开放合并后扣除有效停用并集）
  // 裁进自身窗口，再扣除当前有效预约占用（已取消预约/停用与未兑现候补不阻挡）
  const baseFree: Array<Map<string, Array<[number, number]>>> = items.map((it) => {
    const m = new Map<string, Array<[number, number]>>();
    for (const g of it.groups) {
      for (const id of g.candidates) {
        if (!m.has(id)) m.set(id, resourceFreeSegments(store, id, it.startMin, it.endMin));
      }
    }
    return m;
  });

  // 候选开始分钟闭包，四类来源（值域有限，迭代至收敛）：
  //  1) 基础空闲段起点；
  //  2) 资源冲突传播 s_i = s_j + d_j（仅候选资源集合有交集的项之间）；
  //  3) 关系正向传播：r=(p→c,[lo,hi]) 下 s_c = s_p + d_p + g，g∈[lo,hi]，
  //     从 s_p 派生出 s_p+d_p+lo 与 s_p+d_p+hi 两个端点（区间端点闭包）；
  //  4) 关系反向传播：固定后项开始 s_c 时前项开始 s_p = s_c - d_p - g，
  //     同样派生出 s_c-d_p-hi 与 s_c-d_p-lo 两个端点——最大间隔可借此倒逼
  //     前项提前，逆清单关系也能传播回较早的项。
  // 最小方案按开始分钟归纳，其每个开始必落在该闭包内（含被最大间隔约束的情形）。
  const candidateIds = items.map((it) => {
    const set = new Set<string>();
    for (const g of it.groups) for (const id of g.candidates) set.add(id);
    return set;
  });
  const sharesCandidate = (a: number, b: number): boolean => {
    for (const id of candidateIds[a]) if (candidateIds[b].has(id)) return true;
    return false;
  };
  const inWindow = (i: number, s: number): boolean =>
    s >= items[i].startMin && s + items[i].duration <= items[i].endMin;
  const candStarts: Array<Set<number>> = items.map((it, i) => {
    const set = new Set<number>();
    for (const segs of baseFree[i].values()) {
      for (const [s] of segs) {
        if (inWindow(i, s)) set.add(s);
      }
    }
    return set;
  });
  let changed = true;
  while (changed) {
    changed = false;
    const add = (i: number, s: number): void => {
      if (inWindow(i, s) && !candStarts[i].has(s)) {
        candStarts[i].add(s);
        changed = true;
      }
    };
    for (let j = 0; j < items.length; j++) {
      for (let i = 0; i < items.length; i++) {
        if (i === j) continue;
        for (const s of candStarts[j]) {
          // 资源冲突“顶住”
          if (sharesCandidate(i, j)) add(i, s + items[j].duration);
          // 关系正向：j 为前项、i 为后项
          for (const r of items[j].nextRels) {
            if (r.to - 1 !== i) continue;
            add(i, s + items[j].duration + r.minGap);
            if (r.maxGap !== null) add(i, s + items[j].duration + r.maxGap);
          }
          // 关系反向：j 为后项、i 为前项（逆清单顺序 / 最大间隔倒逼）
          for (const r of items[j].prevRels) {
            if (r.from - 1 !== i) continue;
            add(i, s - items[i].duration - r.minGap);
            if (r.maxGap !== null) add(i, s - items[i].duration - r.maxGap);
          }
        }
      }
    }
  }

  // 固定后项开始 s_c 时，其某一前项 p 允许的开始集合：
  // s_p ∈ [s_c-d_p-hi, s_c-d_p-lo]（maxGap 缺省取 +∞），与候选集及窗口相交
  const prevStartOptions = (rel: FlexRelation, childStart: number): number[] => {
    const p = rel.from - 1;
    const lo = childStart - items[p].duration - (rel.maxGap ?? Number.POSITIVE_INFINITY);
    const hi = childStart - items[p].duration - rel.minGap;
    const out: number[] = [];
    for (const s of candStarts[p]) {
      if (s >= lo && s <= hi) out.push(s);
    }
    return out;
  };

  // 已放置项对各资源的占用（随试探入栈/出栈增减）
  const occById = new Map<string, Array<[number, number]>>();
  // 已放置项的开始分钟（按 0 基项下标）；放置时检查入边，前项必已放置或必然不可行
  const placedStart = new Array<number | null>(items.length).fill(null);

  const search = (idx: number): FlexPlacement[] | null => {
    if (idx === items.length) return [];
    const it = items[idx];
    // 当前空闲段 = 基础空闲段扣除已放置项占用
    const freeById = new Map<string, Array<[number, number]>>();
    for (const [id, segs] of baseFree[idx]) {
      const occ = occById.get(id);
      freeById.set(id, occ !== undefined && occ.length > 0 ? subtractSegments(segs, occ) : segs);
    }
    for (const s of [...candStarts[idx]].sort((a, b) => a - b)) {
      const e = s + it.duration;
      // 入边间隔约束：后项开始 − 前项结束 ∈ [min,max]；
      // 按清单顺序 DFS 时前项尚未放置只可能是逆清单关系，此分支无解（前项
      // 放置时会自行检查出边相容），跳过即可，不会漏掉任何完整方案
      let gapsOk = true;
      for (const r of it.prevRels) {
        const ps = placedStart[r.from - 1];
        if (ps === null) {
          gapsOk = false;
          break;
        }
        const gap = s - (ps + items[r.from - 1].duration);
        if (gap < r.minGap || (r.maxGap !== null && gap > r.maxGap)) {
          gapsOk = false;
          break;
        }
      }
      if (!gapsOk) continue;
      const cache = new Map<string, boolean>();
      const usable = (id: string): boolean => {
        let v = cache.get(id);
        if (v === undefined) {
          v = isFullyCovered(freeById.get(id)!, s, e);
          cache.set(id, v);
        }
        return v;
      };
      for (const picks of assignmentsInLexOrder(it.groups, usable)) {
        for (const id of picks) {
          const occ = occById.get(id) ?? [];
          occ.push([s, e]);
          occById.set(id, occ);
        }
        placedStart[idx] = s;
        const rest = search(idx + 1);
        if (rest !== null) return [{startMin: s, endMin: e, picks}, ...rest];
        placedStart[idx] = null;
        for (const id of picks) occById.get(id)!.pop();
      }
    }
    return null;
  };

  // 逆清单关系（边指向较小序号）下按清单顺序 DFS 无法在放置后项时看到前项：
  // 先以拓扑序（Kahn；结构校验已保证无环）校验关系约束本身是否可满足，并在
  // 每个源点注入其候选开始做受限传播，确认每一项在某条关系链上都有可达的
  // 候选开始。无法通过即无整体解，直接返回 null；通过后再交由上面的 DFS
  // 枚举完整方案（逆清单边在 DFS 中的相容性由“先放置的前项”一侧保证：
  // 序号较小的前项先放置时，其出边后项尚未放置，不检查；后项放置时前项
  // 已放置，正常检查入边）。
  const inDegree = items.map(() => 0);
  for (const r of plan.relations) inDegree[r.to - 1]++;
  const queue: number[] = [];
  for (let i = 0; i < items.length; i++) if (inDegree[i] === 0) queue.push(i);
  const reachable = candStarts.map((set) => new Set<number>(set));
  let visited = 0;
  while (queue.length > 0) {
    const p = queue.shift()!;
    visited++;
    for (const r of items[p].nextRels) {
      const c = r.to - 1;
      for (const sp of reachable[p]) {
        const base = sp + items[p].duration;
        for (const gc of [r.minGap, r.maxGap ?? r.minGap]) {
          const sc = base + gc;
          if (inWindow(c, sc) && candStarts[c].has(sc)) reachable[c].add(sc);
        }
      }
      inDegree[c]--;
      if (inDegree[c] === 0) queue.push(c);
    }
  }
  // visited < items.length 理论不可达（无环已在结构校验保证），保险起见按无解处理
  if (visited < items.length) return null;
  for (let i = 0; i < items.length; i++) {
    if (reachable[i].size === 0) return null;
  }

  return search(0);
}

