  // 逆清单关系（边指向较小序号）下按清单顺序 DFS 无法在放置后项时看到前项：
  // 先以拓扑序（Kahn；结构校验已保证无环）校验关系约束本身是否可满足，并在
  // 每个源点注入其候选开始做受限传播，确认每一项在某条关系链上都有可达的
  // 候选开始。无法通过即无整体解，直接返回 null；通过后再交由上面的 DFS
  // 枚举完整方案（逆清单边在 DFS 中的相容性由“先放置的前项”一侧保证：
  // 序号较小的前项先放置时，其出边后项尚未放置，不检查；后项放置时前项
  // 已放置，正常检查入边）。
  const inDegree = items.map(() => 0);
  for (const r of plan.relations) inDegree[r.to - 1]++;
  const queue: number[] = [];
  for (let i = 0; i < items.length; i++) if (inDegree[i] === 0) queue.push(i);
  const reachable = candStarts.map((set) => new Set<number>(set));
  let visited = 0;
  while (queue.length > 0) {
    const p = queue.shift()!;
    visited++;
    for (const r of items[p].nextRels) {
      const c = r.to - 1;
      for (const sp of reachable[p]) {
        const base = sp + items[p].duration;
        for (const gc of [r.minGap, r.maxGap ?? r.minGap]) {
          const sc = base + gc;
          if (inWindow(c, sc) && candStarts[c].has(sc)) reachable[c].add(sc);
        }
      }
      inDegree[c]--;
      if (inDegree[c] === 0) queue.push(c);
    }
  }
  // visited < items.length 理论不可达（无环已在结构校验保证），保险起见按无解处理
  if (visited < items.length) return null;
  for (let i = 0; i < items.length; i++) {
    if (reachable[i].size === 0) return null;
  }

  return search(0);
}

