          used.delete(id);
        }
      };
      rec(0, new Set(), []);
    }
    return out;
  });
  const feasible = [];
  const chosen = [];
  const rec2 = (i) => {
    if (i === c.items.length) {
      for (let a = 0; a < chosen.length; a++) {
        for (let b = a + 1; b < chosen.length; b++) {
          const shared = chosen[a].picks.some((id) => chosen[b].picks.includes(id));
          if (shared && chosen[a].s < chosen[b].s + c.items[b].dur && chosen[b].s < chosen[a].s + c.items[a].dur) return;
        }
      }
