        if (rnd() < 0.45) {
          const key = `${a}-${b}`;
          if (seen.has(key)) continue;
          seen.add(key);
          const min = [0, 0, 5, 10, 15][Math.floor(rnd() * 5)];
          const rel = {from: a + 1, to: b + 1, minMinutes: min};
          if (rnd() < 0.65) rel.maxMinutes = min + [0, 5, 10, 20, 30][Math.floor(rnd() * 5)];
