// 临时模糊对照：随机小案例，CLI schedule-flex（含关系）逐分钟/逐组合穷举对照
import {spawnSync} from 'node:child_process';
import {mkdtempSync, rmSync, writeFileSync, readFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const APP = join(dirname(fileURLToPath(import.meta.url)), 'app.ts');
const OPEN = '2026-01-01T00:00/2027-01-01T00:00';
const DAY = '2026-10-12T';
const base = 9 * 60; // 09:00

function fmt(min) {
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${DAY}${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function runCli(df, args) {
  const r = spawnSync(process.execPath, [APP, '--data', df, ...args], {encoding: 'utf8'});
  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
}

// 逐分钟枚举全部开始、按组枚举互异资源组合，独立判定并按取舍取最小
function bruteForce(c) {
  const busyById = c.busy;
  const options = c.items.map((it) => {
    const out = [];
    const usableAt = (id, s) => {
      for (const [a, b] of busyById.get(id) ?? []) {
        if (s < b && a < s + it.dur) return false;
      }
      return true;
    };
    for (let s = it.ws; s + it.dur <= it.we; s++) {
      const groups = it.groups;
      const rec = (g, used, picks) => {
        if (g === groups.length) {
          out.push({s, picks: [...picks]});
          return;
        }
        for (const id of groups[g]) {
          if (used.has(id) || !usableAt(id, s)) continue;
          used.add(id);
          picks.push(id);
          rec(g + 1, used, picks);
          picks.pop();
          used.delete(id);
        }
      };
      rec(0, new Set(), []);
    }
    return out;
  });
  const feasible = [];
  const chosen = [];
  const rec2 = (i) => {
    if (i === c.items.length) {
      for (let a = 0; a < chosen.length; a++) {
        for (let b = a + 1; b < chosen.length; b++) {
          const shared = chosen[a].picks.some((id) => chosen[b].picks.includes(id));
          if (shared && chosen[a].s < chosen[b].s + c.items[b].dur && chosen[b].s < chosen[a].s + c.items[a].dur) return;
        }
      }
      for (const r of c.relations) {
        const p = chosen[r.from - 1];
        const q = chosen[r.to - 1];
        const gap = q.s - (p.s + c.items[r.from - 1].dur);
        const max = r.maxMinutes === undefined ? null : r.maxMinutes;
        if (gap < r.minMinutes || (max !== null && gap > max)) return;
      }
      feasible.push(chosen.map((x) => ({s: x.s, picks: [...x.picks]})));
      return;
    }
    for (const o of options[i]) {
      chosen.push(o);
      rec2(i + 1);
      chosen.pop();
    }
  };
  rec2(0);
  if (feasible.length === 0) return null;
  feasible.sort((a, b) => {
    for (let i = 0; i < a.length; i++) {
      if (a[i].s !== b[i].s) return a[i].s - b[i].s;
      for (let g = 0; g < a[i].picks.length; g++) {
        const cmp = a[i].picks[g].localeCompare(b[i].picks[g]);
        if (cmp !== 0) return cmp;
      }
    }
    return 0;
  });
