          const rel = {from: a + 1, to: b + 1, minMinutes: min};
          if (rnd() < 0.65) rel.maxMinutes = min + [0, 5, 10, 20, 30][Math.floor(rnd() * 5)];
          relations.push(rel);
        }
      }
    }
    const manifest = {
      items: items.map((it) => ({
        window: `${fmt(it.ws)}/${fmt(it.we)}`,
        duration: it.dur,
        groups: it.groups,
      })),
      relations,
    };
    const mf = join(dir, `m${caseNo}.json`);
    writeFileSync(mf, JSON.stringify(manifest));

    const expected = bruteForce({items, relations, busy});
    const got = runCli(df, ['schedule-flex', mf]);
    if (expected === null) {
      infeasible++;
      if (got.status !== 1 || !/无整体解/.test(got.stderr)) {
        throw new Error(`案例 ${caseNo}: 期望无解退出 1\n清单: ${JSON.stringify(manifest)}\nstdout:${got.stdout}\nstderr:${got.stderr}`);
      }
      const store = JSON.parse(readFileSync(df, 'utf8'));
      if (store.bookings.length !== busyCount) throw new Error(`案例 ${caseNo}: 无解却写入了预约`);
    } else {
      feasible++;
      if (got.status !== 0) {
        throw new Error(`案例 ${caseNo}: 期望有解\n清单: ${JSON.stringify(manifest)}\n期望: ${JSON.stringify(expected)}\nstderr:${got.stderr}`);
      }
      const plan = parsePlan(got.stdout, n);
      if (!plan) throw new Error(`案例 ${caseNo}: 无法解析输出\n${got.stdout}`);
      for (let i = 0; i < n; i++) {
        if (plan[i].s !== expected[i].s || JSON.stringify(plan[i].picks) !== JSON.stringify(expected[i].picks)) {
          throw new Error(
            `案例 ${caseNo} 第 ${i + 1} 项不一致\n清单: ${JSON.stringify(manifest, null, 1)}\n` +
              `期望: ${JSON.stringify(expected)}\n实际: ${JSON.stringify(plan)}`,
          );
        }
      }
    }
  }
  console.log(`OK: ${N} 例（有解 ${feasible} / 无解 ${infeasible}）`);
} finally {
  rmSync(dir, {recursive: true, force: true});
}

